import{_ as a,o as l,c as t,a4 as i}from"./chunks/framework.2-Vke5-n.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"ログ設計ガイドライン","tagline":"Log Design Guidelines","actions":[{"theme":"brand","text":"ログ設計ガイドライン","link":"./log_guidelines.md"}]}},"headers":[],"relativePath":"documents/forLog/index.md","filePath":"documents/forLog/index.md"}'),r={name:"documents/forLog/index.md"};function o(n,e,s,d,c,u){return l(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>本ガイドラインは、アプリケーションが出力するログの設計規約をまとめたものである。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲・前提条件" tabindex="-1">適用範囲・前提条件 <a class="header-anchor" href="#適用範囲・前提条件" aria-label="Permalink to &quot;適用範囲・前提条件&quot;">​</a></h2><ul><li><strong>対象スコープ</strong><ul><li>アプリケーションが出力するログ（アプリログ）が対象</li><li>AWS CloudTrailやVPCフローログといった、クラウドサービスやインフラストラクチャ側で出力されるログは対象外</li><li>主にバックエンド領域のログを扱う。フロントエンドのログについても一部言及するが、本ガイドラインの主眼にしない</li></ul></li><li><strong>前提条件</strong><ul><li><strong>実行環境</strong>: クラウド利用を前提とする。オンプレミス環境で必要となるファイルベースのログローテーションは考慮しない</li><li><strong>出力方式</strong>: ログはファイルではなく、標準出力を基本とする</li></ul></li></ul><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、八木雅斗、宮崎将太、武田大輝、澁川喜規</li><li><strong>レビュアー</strong>: 募集中</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2026.02.10 <a href="https://future-architect.github.io/articles/20260210a/" target="_blank" rel="noreferrer">ログ設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./log_guidelines.html">ログ設計ガイドライン</a></p></div>',11)])])}const _=a(r,[["render",o]]);export{g as __pageData,_ as default};
